package me.pikanote.companion;
import java.io.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import java.util.*;
/** Portable authenticated encryption; no Android Keystore dependency for restore. */
final class PortableBackup{
 static final byte[] MAGIC={'P','I','K','A','8',0};
 static Cipher cipher(int mode,char[] password,byte[] salt,byte[] nonce)throws Exception{return cipher(mode,password,salt,nonce,MAGIC);}
 static Cipher cipher(int mode,char[] password,byte[] salt,byte[] nonce,byte[] magic)throws Exception{PBEKeySpec spec=new PBEKeySpec(password,salt,210000,256);byte[] key=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(mode,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));c.updateAAD(magic);return c;}finally{Arrays.fill(key,(byte)0);spec.clearPassword();}}
 static void write(Store store,OutputStream out,char[] password)throws Exception{if(password.length<10)throw new IOException("Use at least 10 characters for the backup password");byte[] salt=new byte[16],nonce=new byte[12];SecureRandom random=new SecureRandom();random.nextBytes(salt);random.nextBytes(nonce);out.write(MAGIC);out.write(salt);out.write(nonce);try(CipherOutputStream encrypted=new CipherOutputStream(out,cipher(Cipher.ENCRYPT_MODE,password,salt,nonce))){PhoneBackup.write(store,encrypted,true);}}
 static void restore(Store store,InputStream in,char[] password)throws Exception{DataInputStream data=new DataInputStream(in);byte[] magic=new byte[MAGIC.length],salt=new byte[16],nonce=new byte[12];data.readFully(magic);if(!Arrays.equals(magic,MAGIC)&&!Arrays.equals(magic,new byte[]{80,65,76,65,55,0}))throw new IOException("Choose an encrypted Pika backup");data.readFully(salt);data.readFully(nonce);File clear=File.createTempFile("authenticated-backup-",".zip",store.context.getCacheDir());try{try(CipherInputStream decrypted=new CipherInputStream(data,cipher(Cipher.DECRYPT_MODE,password,salt,nonce,magic));FileOutputStream out=new FileOutputStream(clear)){byte[] block=new byte[8192];int n;long count=0;while((n=decrypted.read(block))>=0){count+=n;if(count>2L*1024*1024*1024||store.context.getCacheDir().getUsableSpace()<n+1048576)throw new IOException("Not enough storage for backup verification");out.write(block,0,n);}out.getFD().sync();}catch(Exception invalid){throw new IOException("Wrong backup password or damaged backup",invalid);}try(InputStream verified=new FileInputStream(clear)){PhoneBackup.restore(store,verified);}}finally{clear.delete();Arrays.fill(password,'\0');}}
}
